/**
 * A post card of PostShowcase with the text on a panel over the lower part of the picture: the category and
 * date, the title, the excerpt and a read link.
 */
import { type JSX } from "solid-js";
import { Badge } from "../primitives/badge/badge";
import { Box } from "../primitives/box/box";
import { Group } from "../primitives/group/group";
import { Link } from "../primitives/link/link";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { MediaFrame } from "../components/media-frame";
import { cn } from "../utils";
import type { Post, PostLabels } from "../blocks/post-card.types";

export type PostOverlayCardProps = {
  p: Post;
  labels: PostLabels;
  ratio?: "4/3" | "16/9";
};

export function PostOverlayCard({ p, labels, ratio = "4/3" }: PostOverlayCardProps) {
  return (
    <Box class="relative overflow-hidden rounded" data-testid="post-overlay">
      <MediaFrame alt={p.title} ratio={ratio} class={(((ratio as string) === "4/3") ? "min-h-80" : "min-h-64")} />
      <Stack gap="2" align="start" class="absolute bottom-4 left-4 right-4 rounded bg-background p-4">
        <Group gap="2" align="center">
          <Badge variant="secondary" size="sm">
            {p.category}
          </Badge>
          <Text size="xs" class="text-muted-foreground">
            {p.date}
          </Text>
        </Group>
        <Title as={3} size="base" weight="semibold">
          {p.title}
        </Title>
        <Text size="sm" class={cn("text-muted-foreground", "line-clamp-2")}>
          {p.excerpt}
        </Text>
        <Link href="#/" size="sm" data-testid="read">
          {labels.read}
          <LucideIcon name="arrow-right" size={16} />
        </Link>
      </Stack>
    </Box>
  );
}
